function TreeInfo([string]$Root){$entries=@(Get-ChildItem -LiteralPath $Root -Recurse -File|Sort-Object FullName|ForEach-Object{[ordered]@{path=$_.FullName.Substring($Root.Length).TrimStart('\').Replace('\','/');bytes=$_.Length;sha256=Hash $_.FullName}});$json=if($entries.Count){@($entries)|ConvertTo-Json -Compress -Depth 3}else{'[]'};$sha=[Security.Cryptography.SHA256]::Create();try{$treeHash=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($json)))).Replace('-','')}finally{$sha.Dispose()};$bytes=0L;foreach($entry in $entries){$bytes+=[long]$entry.bytes};[pscustomobject]@{Hash=$treeHash;Count=$entries.Count;Bytes=$bytes}}
